{"code":"logic_define('craft', function(a, b)
  local recipes = {
    ['wood+wood'] = 'plank',
    ['plank+plank'] = 'table',
    ['stone+wood'] = 'axe',
  }
  if type(a) ~= 'string' or type(b) ~= 'string' then return 'none' end
  local x, y = a, b
  if x > y then x, y = y, x end
  return recipes[x .. '+' .. y] or 'none'
end)
